package com.lianxibu.site.service.sources;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.config.CollectorSecurityConfiguration;import com.lianxibu.site.config.BootstrapSecurityConfiguration;import com.lianxibu.site.controller.collector.SourceContractTelemetryController;
import com.lianxibu.site.domain.protocol.CanonicalJson;import com.lianxibu.site.domain.identity.NodeTokens;import com.lianxibu.site.service.identity.NodeIdentityService;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.util.*;import javax.sql.DataSource;import org.junit.jupiter.api.*;
import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.boot.web.server.context.WebServerApplicationContext;import org.springframework.context.annotation.Import;import org.springframework.context.support.GenericApplicationContext;
class SourceContractTelemetryHttpTest {
 @org.springframework.boot.test.context.TestConfiguration(proxyBeanMethods=false)
 @EnableAutoConfiguration(exclude=org.springframework.boot.jdbc.autoconfigure.DataSourceAutoConfiguration.class)
 @Import({SourceContractTelemetryController.class,CollectorSecurityConfiguration.class,BootstrapSecurityConfiguration.class})
 static class App{}
 SourceContractSnapshotServiceTest f;org.springframework.context.ConfigurableApplicationContext app;HttpClient client;String root;
 DataSource source(){return new SourceContractSnapshotServiceTest().source();}
 @BeforeEach void setup(){f=new SourceContractSnapshotServiceTest(){@Override DataSource source(){return SourceContractTelemetryHttpTest.this.source();}};f.setup();app=new SpringApplicationBuilder(appType()).properties("server.port=0","server.address=127.0.0.1","spring.main.banner-mode=off","logging.level.root=ERROR").initializers(context->install((GenericApplicationContext)context)).run("--site.ops.source-contract.enabled=true","--site.browser.enabled=true","--site.collector.enabled=true","--site.sources.enabled=true");root="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort()+"/api/collector/v1/source-contract-telemetry/"+f.sourceId;client=HttpClient.newHttpClient();}
 Class<?> appType(){return App.class;}
 void install(GenericApplicationContext registry){registry.registerBean(SourceContractSnapshotService.class,()->f.service);registry.registerBean(NodeIdentityService.class,()->new NodeIdentityService(f.nodes,new NodeTokens(new byte[32]),f.clock));}
 @AfterEach void cleanup(){if(client!=null)client.close();if(app!=null)app.close();if(f!=null)f.cleanup();}
 HttpResponse<String> put(String token,String suffix,byte[] raw,boolean extra)throws Exception{var request=HttpRequest.newBuilder(URI.create(root+suffix)).header("Content-Type","application/json").PUT(HttpRequest.BodyPublishers.ofByteArray(raw));if(token!=null)request.header("Authorization","Bearer "+token);if(extra)request.header("Idempotency-Key","fictional-unused-key");return client.send(request.build(),HttpResponse.BodyHandlers.ofString());}
 void code(HttpResponse<String> response,int status,String code){assertEquals(status,response.statusCode(),response.body());assertEquals(code,CanonicalJson.parse(response.body()).at("/error/code").asText());assertEquals("no-store",response.headers().firstValue("Cache-Control").orElseThrow());}
 @Test void actualHttpAndNativeWriterReturnStableFullAckThenRevocationFencesReplay()throws Exception{var body=f.raw(1);code(put(null,"",body,false),401,"unauthenticated");code(put("B".repeat(43),"",body,false),403,"forbidden");var first=put(f.token,"",body,false);assertEquals(200,first.statusCode(),first.body());var data=CanonicalJson.parse(first.body()).get("data");assertEquals(7,data.size());assertEquals(f.sourceId,data.get("source_id").asText());assertEquals("source-contract-telemetry-ack-v1",data.get("schema_version").asText());assertEquals(CanonicalJson.hash(CanonicalJson.Domain.ACTION,CanonicalJson.parse(body)),data.get("payload_hash").asText());assertEquals(data,CanonicalJson.parse(put(f.token,"",body,false).body()).get("data"));assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));assertEquals(1,f.nodes.revoke(f.nodeId,1));code(put(f.token,"",body,false),403,"forbidden");}
 @Test void closedWireUnknownDuplicateCapacityQueryAndTypeRejectWithoutWrites()throws Exception{var body=f.raw(1);code(put(f.token,"?unexpected=1",body,false),400,"protocol_error");code(put(f.token,"",body,true),400,"protocol_error");var raw=new String(body,StandardCharsets.UTF_8);code(put(f.token,"",raw.replace("\"events\":","\"unknown\":true,\"events\":").getBytes(StandardCharsets.UTF_8),false),400,"protocol_error");code(put(f.token,"",raw.replace("\"config_version\":1","\"config_version\":1,\"config_version\":1").getBytes(StandardCharsets.UTF_8),false),400,"protocol_error");code(put(f.token,"",raw.replace("\"config_version\":1","\"config_version\":0").getBytes(StandardCharsets.UTF_8),false),422,"validation");code(put(f.token,"",new byte[32769],false),413,"payload_too_large");assertEquals(0,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));}
 @Test void staleSourceOrCorruptNativeProofCannotClaimSuccessOrLeakStorage()throws Exception{var body=f.raw(1);assertEquals(200,put(f.token,"",body,false).statusCode());f.f.jdbc.update("UPDATE sources SET config_revision=config_revision+1 WHERE id=?",f.sourceId);code(put(f.token,"",f.raw(2),false),409,"stale_config");f.f.jdbc.update("UPDATE request_receipts SET request_hash=?",new byte[32]);var damaged=put(f.token,"",body,false);code(damaged,503,"temporarily_unavailable");assertEquals("1",damaged.headers().firstValue("Retry-After").orElseThrow());assertFalse(damaged.body().contains("SELECT"));assertFalse(damaged.body().contains(f.token));assertFalse(damaged.body().contains("source snapshot proof"));}
}
